      supabase.from("model_summaries").select("avg_rating,review_count,summary").eq("model_id", model_id).maybeSingle(),
      supabase.from("reviews").select("rating,content,created_at,profile:profiles(display_name,username)").eq("model_id", model_id).order("created_at", { ascending: false }).limit(review_limit ?? 20)
